import type { BlogPost } from './blog';

type Copy = { title: string; excerpt: string; seoTitle: string; seoDesc: string; h: string; p: string };
const make = (copy: Record<string, Copy>): BlogPost['i18n'] => Object.fromEntries(
  Object.entries(copy).map(([lang, c]) => [lang, {
    title: c.title, excerpt: c.excerpt, seoTitle: c.seoTitle, seoDesc: c.seoDesc,
    sections: [{ h: c.h, p: [c.p] }],
  }]),
) as BlogPost['i18n'];

const overview = make({
  ru:{title:'Jelly Ko: каталог корейского ухода с акцентом на рефиллы',excerpt:'Ассортимент Jelly Ko — 14 SKU в трёх группах, четыре базовых средства продаются с подходящим рефиллом.',seoTitle:'Jelly Ko: каталог корейского ухода с рефиллами · Teranova',seoDesc:'Обзор каталога Jelly Ko: уход за лицом с рефиллами, уход за губами и точечный уход, аксессуары. Производство — Корея.',h:'Что есть в каталоге',p:'Ассортимент Jelly Ko, корейского бренда со штаб-квартирой в Сеуле, охватывает 14 SKU в трёх группах каталога: уход за лицом с системой рефиллов (крем-стим, ночная маска, тонер, скраб-пенка, суфле-сыворотка и ночная сыворотка — четыре из них продаются вместе с подходящим рефиллом), уход за губами и точечный уход (маска для губ и гидроколлоидные патчи от воспалений) и аксессуары (силиконовая кисть для маски и резинка для волос). Четыре средства — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum и Be Jelly Overnight Dream Serum — продаются с пауч-рефиллом или travel-pack той же формулы и той же серии UPC. По собственным материалам бренда, формулы описываются как «Chemist Formulated», производство — в Корее (штаб-квартира в Сеуле), склады — в Корее, Австралии и США.'},
  en:{title:'Jelly Ko: a refill-first Korean skincare catalog',excerpt:'The Jelly Ko range spans 14 SKUs in three groups, with four core products sold alongside a matching refill.',seoTitle:'Jelly Ko: refillable Korean skincare catalog · Teranova',seoDesc:'Overview of the Jelly Ko catalog: refillable face care, lip & spot care and accessories, made in Korea.',h:'What the catalog holds',p:'The Jelly Ko range, from the Korean brand headquartered in Seoul, spans 14 SKUs across three catalog groups: refillable face care (steam cream, sleeping mask, toner, scrub foam, soufflé serum and overnight serum, four of them sold with a matching refill), lip & spot care (a lip mask and hydrocolloid pimple patches) and accessories (a silicone mask brush and a scrunchie). Four products — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum and Be Jelly Overnight Dream Serum — are sold with a refill pouch or travel pack using the same formula and the same UPC series. The brand describes its formulas as "Chemist Formulated" and manufactures in Korea (HQ in Seoul); per its own materials, it ships from warehouses in Korea, Australia and the US.'},
  ko:{title:'젤리코(Jelly Ko): 리필 중심의 한국 스킨케어 카탈로그',excerpt:'젤리코 제품군은 3개 그룹에 걸쳐 14개 SKU로 구성되며, 그중 핵심 제품 4종은 전용 리필과 함께 판매됩니다.',seoTitle:'젤리코: 리필 가능한 한국 스킨케어 카탈로그 · Teranova',seoDesc:'젤리코 카탈로그 개요: 리필 가능한 페이스 케어, 립 & 스팟 케어, 액세서리, 한국산(Made in Korea) 제품.',h:'카탈로그 구성',p:'서울에 본사를 둔 한국 브랜드 젤리코의 제품군은 3개 카탈로그 그룹, 총 14개 SKU로 구성됩니다: 리필 가능한 페이스 케어(스팀 크림, 슬리핑 마스크, 토너, 스크럽 폼, 수플레 세럼, 오버나이트 세럼이며 이 중 4종은 전용 리필과 함께 판매), 립 & 스팟 케어(립 마스크와 하이드로콜로이드 여드름 패치), 액세서리(실리콘 마스크 브러시와 스크런치). Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum, Be Jelly Overnight Dream Serum 4종 제품은 동일한 포뮬러와 동일한 UPC 시리즈를 사용하는 리필 파우치 또는 트래블 팩과 함께 판매됩니다. 브랜드는 자사 포뮬러를 "Chemist Formulated"로 소개하며 한국(본사 서울)에서 제조합니다. 브랜드 자체 자료에 따르면 한국, 호주, 미국의 창고에서 발송됩니다.'},
  zh:{title:'Jelly Ko：以补充装为核心的韩国护肤产品目录',excerpt:'Jelly Ko系列涵盖三大类共14个单品(SKU),其中4款核心产品均配有对应的补充装。',seoTitle:'Jelly Ko：可补充装韩国护肤品目录 · Teranova',seoDesc:'Jelly Ko产品目录概览:可补充装面部护理、唇部与局部护理及配件,韩国制造。',h:'产品目录构成',p:'Jelly Ko是一家总部位于首尔的韩国品牌,其产品系列涵盖三大目录类别,共14个单品(SKU):可补充装面部护理(蒸汽面霜、睡眠面膜、爽肤水、磨砂洁面泡沫、舒芙蕾精华和晚安精华,其中4款配有对应补充装)、唇部与局部护理(唇膜和水胶体祛痘贴)以及配件(硅胶面膜刷和发圈)。Bubble Tea Steam Cream、Dewy Glaze Toner、White Truffle Soufflé Serum和Be Jelly Overnight Dream Serum这4款产品均配有补充装软包或旅行装,使用相同配方并共用同一UPC编码系列。该品牌将其配方描述为"Chemist Formulated"(化学师配方),产品在韩国制造(总部位于首尔);据其自有资料显示,产品从韩国、澳大利亚和美国的仓库发货。'},
  ja:{title:'Jelly Ko:リフィル重視の韓国スキンケアカタログ',excerpt:'Jelly Koのラインナップは3つのグループにわたる14品番(SKU)で構成され、コア製品4点にはそれぞれ専用リフィルが用意されています。',seoTitle:'Jelly Ko:リフィル対応韓国スキンケアカタログ · Teranova',seoDesc:'Jelly Koカタログの概要:リフィル対応フェイスケア、リップ&スポットケア、アクセサリー、韓国製。',h:'カタログの構成',p:'ソウルに本社を置く韓国ブランドJelly Koのラインナップは、3つのカタロググループにわたる14品番(SKU)で構成されています:リフィル対応フェイスケア(スチームクリーム、スリーピングマスク、トナー、スクラブフォーム、スフレセラム、オーバーナイトセラムで、このうち4点には専用リフィルが用意されています)、リップ&スポットケア(リップマスクとハイドロコロイドニキビパッチ)、アクセサリー(シリコン製マスクブラシとシュシュ)。Bubble Tea Steam Cream、Dewy Glaze Toner、White Truffle Soufflé Serum、Be Jelly Overnight Dream Serumの4製品は、同じ処方・同じUPCシリーズを使用したリフィルパウチまたはトラベルパックとともに販売されています。ブランドは自社の処方を「Chemist Formulated」と表現し、韓国(本社:ソウル)で製造しています。ブランド自身の資料によると、韓国・オーストラリア・米国の倉庫から発送されています。'},
  it:{title:'Jelly Ko: un catalogo di skincare coreana pensato per le ricariche',excerpt:'La gamma Jelly Ko comprende 14 SKU in tre gruppi, con quattro prodotti principali venduti insieme a una ricarica corrispondente.',seoTitle:'Jelly Ko: catalogo di skincare coreana ricaricabile · Teranova',seoDesc:'Panoramica del catalogo Jelly Ko: cura del viso ricaricabile, cura di labbra e imperfezioni e accessori, made in Korea.',h:'Cosa contiene il catalogo',p:'La gamma Jelly Ko, del marchio coreano con sede a Seoul, comprende 14 SKU suddivisi in tre gruppi del catalogo: cura del viso ricaricabile (crema a vapore, maschera notte, tonico, schiuma scrub, siero soufflé e siero overnight, quattro dei quali venduti con una ricarica corrispondente), cura di labbra e imperfezioni (una maschera labbra e cerotti idrocolloidali per brufoli) e accessori (un pennello in silicone per maschere e uno scrunchie). Quattro prodotti — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum e Be Jelly Overnight Dream Serum — sono venduti con una ricarica in busta o un travel pack basato sulla stessa formula e sulla stessa serie di codici UPC. Il marchio descrive le proprie formule come «Chemist Formulated» e produce in Corea (sede a Seoul); secondo i propri materiali, spedisce da magazzini in Corea, Australia e Stati Uniti.'},
  de:{title:'Jelly Ko: ein koreanischer Skincare-Katalog mit Fokus auf Nachfüllpackungen',excerpt:'Das Jelly-Ko-Sortiment umfasst 14 SKUs in drei Gruppen, wobei vier Kernprodukte zusammen mit einer passenden Nachfüllpackung verkauft werden.',seoTitle:'Jelly Ko: nachfüllbarer koreanischer Skincare-Katalog · Teranova',seoDesc:'Überblick über den Jelly-Ko-Katalog: nachfüllbare Gesichtspflege, Lippen- und Pickelpflege sowie Zubehör, hergestellt in Korea.',h:'Was der Katalog umfasst',p:'Das Jelly-Ko-Sortiment der koreanischen Marke mit Hauptsitz in Seoul umfasst 14 SKUs in drei Katalog-Gruppen: nachfüllbare Gesichtspflege (Dampfcreme, Schlafmaske, Toner, Peeling-Schaum, Soufflé-Serum und Overnight-Serum, vier davon mit passender Nachfüllpackung erhältlich), Lippen- und Pickelpflege (eine Lippenmaske und Hydrokolloid-Pickelpatches) sowie Zubehör (eine Silikon-Maskenbürste und ein Scrunchie). Vier Produkte — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum und Be Jelly Overnight Dream Serum — werden mit einem Nachfüllbeutel oder Reisepack verkauft, der dieselbe Formel und dieselbe UPC-Serie verwendet. Die Marke bezeichnet ihre Formeln als „Chemist Formulated" und produziert in Korea (Hauptsitz in Seoul); nach eigenen Angaben versendet sie aus Lagern in Korea, Australien und den USA.'},
  fr:{title:'Jelly Ko : un catalogue de skincare coréenne pensé pour la recharge',excerpt:'La gamme Jelly Ko compte 14 références réparties en trois groupes, dont quatre produits phares vendus avec une recharge correspondante.',seoTitle:'Jelly Ko : catalogue de skincare coréenne rechargeable · Teranova',seoDesc:'Présentation du catalogue Jelly Ko : soins du visage rechargeables, soins des lèvres et des imperfections, et accessoires, fabriqués en Corée.',h:'Ce que contient le catalogue',p:'La gamme Jelly Ko, de la marque coréenne dont le siège est à Séoul, compte 14 références réparties en trois groupes de catalogue : soins du visage rechargeables (crème vapeur, masque de nuit, tonique, mousse exfoliante, sérum soufflé et sérum de nuit, quatre d\'entre eux étant vendus avec une recharge correspondante), soins des lèvres et des imperfections (un masque à lèvres et des patchs hydrocolloïdes anti-imperfections) et accessoires (un pinceau en silicone pour masque et un chouchou). Quatre produits — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum et Be Jelly Overnight Dream Serum — sont vendus avec une recharge en sachet ou un format voyage utilisant la même formule et la même série de codes UPC. La marque décrit ses formules comme « Chemist Formulated » et fabrique en Corée (siège à Séoul) ; selon ses propres documents, elle expédie depuis des entrepôts en Corée, en Australie et aux États-Unis.'},
  tr:{title:'Jelly Ko: yeniden doldurmaya öncelik veren bir Kore cilt bakımı kataloğu',excerpt:'Jelly Ko serisi üç grupta 14 ürün koduna yayılır; dört ana ürün, eşleşen bir yeniden doldurma paketiyle birlikte satılır.',seoTitle:'Jelly Ko: yeniden doldurulabilir Kore cilt bakımı kataloğu · Teranova',seoDesc:'Jelly Ko kataloğuna genel bakış: yeniden doldurulabilir yüz bakımı, dudak ve leke bakımı ve aksesuarlar, Kore\'de üretilmiştir.',h:'Katalogda neler var',p:'Merkezi Seul\'de bulunan Koreli marka Jelly Ko\'nun serisi, üç katalog grubunda toplam 14 ürün koduna yayılır: yeniden doldurulabilir yüz bakımı (buhar kremi, uyku maskesi, tonik, peeling köpüğü, sufle serum ve gece serumu; bunlardan dördü eşleşen bir yeniden doldurma paketiyle satılır), dudak ve leke bakımı (bir dudak maskesi ve hidrokolloid sivilce bantları) ve aksesuarlar (silikon bir maske fırçası ve bir scrunchie). Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum ve Be Jelly Overnight Dream Serum olmak üzere dört ürün, aynı formülü ve aynı UPC serisini kullanan bir yeniden doldurma poşeti veya seyahat paketiyle satılmaktadır. Marka, formüllerini "Chemist Formulated" olarak tanımlıyor ve üretimini Kore\'de (merkezi Seul) yapıyor; kendi materyallerine göre Kore, Avustralya ve ABD\'deki depolardan gönderim yapıyor.'},
  es:{title:'Jelly Ko: un catálogo coreano de cuidado de la piel centrado en los recambios',excerpt:'La gama Jelly Ko abarca 14 SKU en tres grupos, con cuatro productos principales que se venden junto con un recambio equivalente.',seoTitle:'Jelly Ko: catálogo coreano de cuidado de la piel recargable · Teranova',seoDesc:'Panorama del catálogo Jelly Ko: cuidado facial recargable, cuidado de labios y manchas, y accesorios, fabricados en Corea.',h:'Qué incluye el catálogo',p:'La gama Jelly Ko, de la marca coreana con sede en Seúl, abarca 14 SKU distribuidos en tres grupos del catálogo: cuidado facial recargable (crema al vapor, mascarilla nocturna, tónico, espuma exfoliante, sérum soufflé y sérum de noche, cuatro de ellos vendidos con su recambio equivalente), cuidado de labios y manchas (una mascarilla labial y parches hidrocoloides para espinillas) y accesorios (un cepillo de silicona para mascarillas y una coletera). Cuatro productos —Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum y Be Jelly Overnight Dream Serum— se venden con una bolsa de recambio o un pack de viaje que usan la misma fórmula y la misma serie de códigos UPC. La marca describe sus fórmulas como "Chemist Formulated" y fabrica en Corea (sede en Seúl); según sus propios materiales, envía desde almacenes en Corea, Australia y Estados Unidos.'},
  pt:{title:'Jelly Ko: um catálogo coreano de skincare focado em recargas',excerpt:'A linha Jelly Ko abrange 14 SKUs em três grupos, com quatro produtos principais vendidos junto com uma recarga correspondente.',seoTitle:'Jelly Ko: catálogo coreano de skincare recarregável · Teranova',seoDesc:'Panorama do catálogo Jelly Ko: cuidados faciais recarregáveis, cuidados com lábios e manchas, e acessórios, fabricados na Coreia.',h:'O que o catálogo traz',p:'A linha Jelly Ko, da marca coreana sediada em Seul, abrange 14 SKUs distribuídos em três grupos do catálogo: cuidados faciais recarregáveis (creme a vapor, máscara noturna, tônico, espuma esfoliante, sérum soufflé e sérum noturno, quatro deles vendidos com uma recarga correspondente), cuidados com lábios e manchas (uma máscara labial e adesivos de hidrocoloide para espinhas) e acessórios (uma escova de silicone para máscaras e um prendedor de cabelo). Quatro produtos — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum e Be Jelly Overnight Dream Serum — são vendidos com uma bolsa de recarga ou um pacote de viagem que usam a mesma fórmula e a mesma série de códigos UPC. A marca descreve suas fórmulas como "Chemist Formulated" e fabrica na Coreia (sede em Seul); segundo seus próprios materiais, envia a partir de armazéns na Coreia, na Austrália e nos Estados Unidos.'},
  he:{title:'Jelly Ko: קטלוג קוריאני לטיפוח עור המתמקד במילוי חוזר',excerpt:'קו המוצרים של Jelly Ko כולל 14 מק"טים בשלוש קבוצות, עם ארבעה מוצרי יסוד שנמכרים לצד מילוי חוזר מתאים.',seoTitle:'Jelly Ko: קטלוג טיפוח קוריאני עם מילוי חוזר · Teranova',seoDesc:'סקירה של קטלוג Jelly Ko: טיפוח פנים עם מילוי חוזר, טיפוח שפתיים ונקודות ואביזרים, תוצרת קוריאה.',h:'מה כולל הקטלוג',p:'קו המוצרים של Jelly Ko, מהמותג הקוריאני שמרכזו בסיאול, כולל 14 מק"טים בשלוש קבוצות קטלוג: טיפוח פנים עם מילוי חוזר (קרם קיטור, מסכת לילה, טונר, קצף קילוף, סרום סופלה וסרום לילה, ארבעה מהם נמכרים עם מילוי חוזר מתאים), טיפוח שפתיים ונקודות (מסכת שפתיים ומדבקות הידרוקולואיד לפצעונים) ואביזרים (מברשת סיליקון למסכות וגומייה לשיער). ארבעה מוצרים — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum ו-Be Jelly Overnight Dream Serum — נמכרים עם שקית מילוי חוזר או אריזת נסיעות באותה פורמולה ובאותה סדרת קודי UPC. המותג מתאר את הפורמולות שלו כ"Chemist Formulated" ומייצר בקוריאה (מרכז בסיאול); לפי החומרים שלו, הוא משגר ממחסנים בקוריאה, באוסטרליה ובארצות הברית.'},
  hi:{title:'Jelly Ko: रीफिल-फर्स्ट कोरियाई स्किनकेयर कैटलॉग',excerpt:'Jelly Ko रेंज में तीन समूहों में 14 SKU शामिल हैं, जिनमें चार मुख्य उत्पाद एक मिलते-जुलते रीफिल के साथ बेचे जाते हैं।',seoTitle:'Jelly Ko: रीफिल योग्य कोरियाई स्किनकेयर कैटलॉग · Teranova',seoDesc:'Jelly Ko कैटलॉग का अवलोकन: रीफिल योग्य फेस केयर, लिप एंड स्पॉट केयर और एक्सेसरीज़, कोरिया में निर्मित।',h:'कैटलॉग में क्या शामिल है',p:'सियोल में मुख्यालय वाले कोरियाई ब्रांड Jelly Ko की रेंज में तीन कैटलॉग समूहों में 14 SKU शामिल हैं: रीफिल योग्य फेस केयर (स्टीम क्रीम, स्लीपिंग मास्क, टोनर, स्क्रब फोम, सूफले सीरम और ओवरनाइट सीरम, जिनमें से चार एक मिलते-जुलते रीफिल के साथ बेचे जाते हैं), लिप एंड स्पॉट केयर (एक लिप मास्क और हाइड्रोकोलॉइड पिंपल पैच) और एक्सेसरीज़ (एक सिलिकॉन मास्क ब्रश और एक स्क्रंची)। चार उत्पाद — Bubble Tea Steam Cream, Dewy Glaze Toner, White Truffle Soufflé Serum और Be Jelly Overnight Dream Serum — एक रीफिल पाउच या ट्रैवल पैक के साथ बेचे जाते हैं, जो एक ही फॉर्मूला और एक ही UPC सीरीज़ का उपयोग करते हैं। ब्रांड अपने फॉर्मूलों को "Chemist Formulated" बताता है और कोरिया में निर्माण करता है (मुख्यालय सियोल में); अपनी सामग्री के अनुसार, यह कोरिया, ऑस्ट्रेलिया और अमेरिका के वेयरहाउस से शिपिंग करता है।'},
  ar:{title:'Jelly Ko: كتالوج عناية كورية يركّز على إعادة التعبئة',excerpt:'تضم تشكيلة Jelly Ko 14 منتجًا ضمن ثلاث مجموعات، مع أربعة منتجات أساسية تُباع مع عبوة تعبئة مطابقة.',seoTitle:'Jelly Ko: كتالوج عناية كورية قابل لإعادة التعبئة · Teranova',seoDesc:'نظرة عامة على كتالوج Jelly Ko: عناية بالوجه قابلة لإعادة التعبئة، عناية بالشفاه والبقع، وإكسسوارات، صنع في كوريا.',h:'ما يحتويه الكتالوج',p:'تضم تشكيلة Jelly Ko، العلامة الكورية التي يقع مقرها الرئيسي في سيول، 14 منتجًا ضمن ثلاث مجموعات في الكتالوج: عناية بالوجه قابلة لإعادة التعبئة (كريم بالبخار، قناع للنوم، تونر، رغوة تقشير، سيروم سوفليه، وسيروم ليلي، تُباع أربعة منها مع عبوة تعبئة مطابقة)، وعناية بالشفاه والبقع (قناع للشفاه ولصقات هيدروكولويد لحب الشباب)، وإكسسوارات (فرشاة سيليكون للقناع وربطة شعر). تُباع أربعة منتجات — Bubble Tea Steam Cream، وDewy Glaze Toner، وWhite Truffle Soufflé Serum، وBe Jelly Overnight Dream Serum — مع كيس تعبئة أو عبوة سفر تستخدم نفس التركيبة ونفس سلسلة رموز UPC. تصف العلامة تركيباتها بأنها "Chemist Formulated" (مُركَّبة من قِبل كيميائيين متخصصين) وتُصنَّع في كوريا (المقر الرئيسي في سيول)؛ وبحسب موادها الخاصة، تشحن من مستودعات في كوريا وأستراليا والولايات المتحدة.'},
});

const refillSystem = make({
  ru:{title:'Рефилл-система Jelly Ko: четыре формулы, один пауч',excerpt:'Четыре средства Jelly Ko продаются с рефилл-паучем или travel-pack — по заявлению бренда, это снижает расход пластика или стекла на 80–90%.',seoTitle:'Как устроены рефиллы Jelly Ko · Teranova',seoDesc:'Рефилл-паучи Jelly Ko для Steam Cream, Dewy Glaze Toner, Soufflé Serum и Overnight Dream Serum — состав и заявленная экономия пластика.',h:'Как устроена программа рефиллов',p:'Собственные материалы бренда описывают линейку как «4x Award Winning Refillable Korean Skincare» — четыре базовые формулы с рефиллами. Рефилл-пауч Bubble Tea Steam Cream (UPC 8809083978402, 50 г) содержит Grape Seed Oil, Beta Glucan, Niacinamide 2% и Adenosine — его переливают в исходную банку или используют отдельно в поездке; по данным бренда, он получил награду Prevention Beauty «Best Refillable Skincare» в 2025 году. Рефилл Dewy Glaze Toner (UPC 8809083978037, 155 г) продаётся и как пауч, и как travel-pack со своей крышкой; по заявлению бренда, это сокращает использование пластика более чем на 90% по сравнению с покупкой новой бутылки каждый раз. Рефилл White Truffle Soufflé Serum (UPC 8809083977412, 50 мл) и рефилл/travel-pack Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 мл) устроены так же и повторяют состав оригинала; по заявлению бренда, рефилл Soufflé Serum сокращает использование пластика и стекла более чем на 80%. Cherry Blossom Sleeping Mask и Cinnamon Toast Sugar Scrub Foam рефиллами не продаются.'},
  en:{title:"Jelly Ko's refill program: four formulas, one pouch system",excerpt:'Four Jelly Ko products ship with a matching refill pouch or travel pack, each claimed by the brand to cut plastic or glass use by 80-90%.',seoTitle:'Jelly Ko refill system explained · Teranova',seoDesc:"How Jelly Ko's refill pouches work for the Steam Cream, Dewy Glaze Toner, Soufflé Serum and Overnight Dream Serum.",h:'How the refill program works',p:'The brand\'s own materials describe the range as "4x Award Winning Refillable Korean Skincare," built around four core formulas. The Bubble Tea Steam Cream refill pouch (UPC 8809083978402, 50 g) carries Grape Seed Oil, Beta Glucan, Niacinamide 2% and Adenosine, poured into the original jar or used on its own while travelling; per the brand, it won the Prevention Beauty "Best Refillable Skincare" award in 2025. The Dewy Glaze Toner refill (UPC 8809083978037, 155 g) is sold both as a pouch and as a travel pack with its own cap, and the brand states it cuts plastic use by more than 90% against buying a new bottle each time. The White Truffle Soufflé Serum refill (UPC 8809083977412, 50 ml) and the Be Jelly Overnight Dream Serum refill/travel pack (UPC 8809083977382, 50 ml) follow the same approach, each matching its original formula; the brand states the Soufflé Serum refill cuts plastic and glass use by more than 80%. The Cherry Blossom Sleeping Mask and the Cinnamon Toast Sugar Scrub Foam are not sold as refills.'},
  ko:{title:'젤리코 리필 프로그램: 4가지 포뮬러, 하나의 파우치 시스템',excerpt:'젤리코 제품 4종이 전용 리필 파우치 또는 트래블 팩과 함께 판매되며, 브랜드에 따르면 각각 플라스틱 또는 유리 사용량을 80~90% 줄인다고 합니다.',seoTitle:'젤리코 리필 시스템 설명 · Teranova',seoDesc:'Steam Cream, Dewy Glaze Toner, Soufflé Serum, Overnight Dream Serum을 위한 젤리코 리필 파우치의 작동 방식.',h:'리필 프로그램 작동 방식',p:'브랜드 자체 자료에 따르면 이 라인은 네 가지 핵심 포뮬러를 중심으로 구성된 "4x Award Winning Refillable Korean Skincare"로 소개된다. Bubble Tea Steam Cream 리필 파우치(UPC 8809083978402, 50g)에는 Grape Seed Oil, Beta Glucan, Niacinamide 2%, Adenosine가 함유되어 있으며, 기존 용기에 부어 사용하거나 여행 중 단독으로 사용할 수 있다. 브랜드에 따르면 이 제품은 2025년 Prevention Beauty의 "Best Refillable Skincare" 상을 수상했다. Dewy Glaze Toner 리필(UPC 8809083978037, 155g)은 파우치형과 자체 캡이 있는 여행용 팩 두 가지로 판매되며, 브랜드는 매번 새 병을 구매하는 경우에 비해 플라스틱 사용량을 90% 이상 줄인다고 밝힌다. White Truffle Soufflé Serum 리필(UPC 8809083977412, 50ml)과 Be Jelly Overnight Dream Serum 리필/여행용 팩(UPC 8809083977382, 50ml)도 동일한 방식을 따르며, 각각 기존 포뮬러와 동일하다. 브랜드는 Soufflé Serum 리필이 플라스틱 및 유리 사용량을 80% 이상 줄인다고 밝힌다. Cherry Blossom Sleeping Mask와 Cinnamon Toast Sugar Scrub Foam은 리필 제품으로 판매되지 않는다.'},
  zh:{title:'Jelly Ko补充装计划:4种配方,一套补充袋系统',excerpt:'Jelly Ko的4款产品配有对应的补充袋或旅行装,据品牌称,每款产品可将塑料或玻璃用量减少80%至90%。',seoTitle:'Jelly Ko补充装系统详解 · Teranova',seoDesc:'Jelly Ko的Steam Cream、Dewy Glaze Toner、Soufflé Serum和Overnight Dream Serum补充袋如何运作。',h:'补充装计划的运作方式',p:'据品牌自身资料介绍,该系列被称为"4x Award Winning Refillable Korean Skincare",围绕四款核心配方打造。Bubble Tea Steam Cream补充装(UPC 8809083978402,50克)含有Grape Seed Oil、Beta Glucan、Niacinamide 2%和Adenosine成分,可倒入原装瓶中使用,也可在旅行时单独使用;据品牌介绍,该产品于2025年获得Prevention Beauty的"Best Refillable Skincare"奖项。Dewy Glaze Toner补充装(UPC 8809083978037,155克)既有袋装,也有带独立瓶盖的旅行装,品牌表示,与每次购买新瓶相比,该产品可减少90%以上的塑料使用量。White Truffle Soufflé Serum补充装(UPC 8809083977412,50毫升)和Be Jelly Overnight Dream Serum补充装/旅行装(UPC 8809083977382,50毫升)采用相同的方式,配方均与原装产品一致;品牌表示,Soufflé Serum补充装可减少80%以上的塑料和玻璃使用量。Cherry Blossom Sleeping Mask和Cinnamon Toast Sugar Scrub Foam不提供补充装。'},
  ja:{title:'Jelly Koのリフィルプログラム:4つの処方、1つのパウチシステム',excerpt:'Jelly Koの4製品には専用のリフィルパウチまたはトラベルパックが用意されており、ブランドによるとそれぞれプラスチックまたはガラスの使用量を80~90%削減するとされています。',seoTitle:'Jelly Koのリフィルシステム解説 · Teranova',seoDesc:'Steam Cream、Dewy Glaze Toner、Soufflé Serum、Overnight Dream SerumにおけるJelly Koのリフィルパウチの仕組み。',h:'リフィルプログラムの仕組み',p:'ブランド自身の資料によると、このラインは4つの主要フォーミュラを中心に構成された「4x Award Winning Refillable Korean Skincare」として紹介されている。Bubble Tea Steam Creamのリフィルパウチ(UPC 8809083978402、50g)にはGrape Seed Oil、Beta Glucan、Niacinamide 2%、Adenosineが含まれており、元のジャーに詰め替えて使用するか、旅行中は単独で使用できる。ブランドによると、本製品は2025年にPrevention Beautyの「Best Refillable Skincare」賞を受賞した。Dewy Glaze Tonerのリフィル(UPC 8809083978037、155g)はパウチ版と専用キャップ付きのトラベルパック版の両方で販売されており、ブランドは毎回新しいボトルを購入する場合と比べてプラスチック使用量を90%以上削減すると述べている。White Truffle Soufflé Serumのリフィル(UPC 8809083977412、50ml)とBe Jelly Overnight Dream Serumのリフィル/トラベルパック(UPC 8809083977382、50ml)も同様の方式を採用しており、それぞれ元のフォーミュラと同一である。ブランドは、Soufflé Serumのリフィルがプラスチックおよびガラスの使用量を80%以上削減すると述べている。Cherry Blossom Sleeping MaskとCinnamon Toast Sugar Scrub Foamはリフィル製品として販売されていない。'},
  it:{title:"Il programma di ricarica di Jelly Ko: quattro formule, un unico sistema a busta",excerpt:"Quattro prodotti Jelly Ko vengono venduti con una ricarica in busta o un travel pack corrispondente; per ciascuno il marchio dichiara una riduzione dell'uso di plastica o vetro dell'80-90%.",seoTitle:'Il sistema di ricarica Jelly Ko spiegato · Teranova',seoDesc:'Come funzionano le ricariche in busta di Jelly Ko per Steam Cream, Dewy Glaze Toner, Soufflé Serum e Overnight Dream Serum.',h:'Come funziona il programma di ricarica',p:'Secondo i materiali del marchio stesso, la gamma viene descritta come "4x Award Winning Refillable Korean Skincare", costruita attorno a quattro formule principali. La confezione di ricarica Bubble Tea Steam Cream (UPC 8809083978402, 50 g) contiene Grape Seed Oil, Beta Glucan, Niacinamide al 2% e Adenosine, e può essere versata nel vasetto originale oppure usata da sola in viaggio; secondo il marchio, ha vinto il premio "Best Refillable Skincare" di Prevention Beauty nel 2025. La ricarica Dewy Glaze Toner (UPC 8809083978037, 155 g) è venduta sia come busta sia come confezione da viaggio con tappo proprio, e il marchio dichiara che riduce l\'uso di plastica di oltre il 90% rispetto all\'acquisto di una nuova bottiglia ogni volta. La ricarica White Truffle Soufflé Serum (UPC 8809083977412, 50 ml) e la ricarica/confezione da viaggio Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 ml) seguono lo stesso approccio, corrispondendo ciascuna alla formula originale; il marchio dichiara che la ricarica del Soufflé Serum riduce l\'uso di plastica e vetro di oltre l\'80%. Il Cherry Blossom Sleeping Mask e il Cinnamon Toast Sugar Scrub Foam non sono venduti come ricariche.'},
  de:{title:'Das Nachfüllprogramm von Jelly Ko: vier Formeln, ein Beutelsystem',excerpt:'Vier Jelly-Ko-Produkte werden mit einer passenden Nachfüllpackung oder einem Reisepack verkauft; die Marke gibt für jedes an, den Plastik- oder Glasverbrauch um 80-90 % zu senken.',seoTitle:'Das Jelly-Ko-Nachfüllsystem erklärt · Teranova',seoDesc:'Wie die Nachfüllbeutel von Jelly Ko für Steam Cream, Dewy Glaze Toner, Soufflé Serum und Overnight Dream Serum funktionieren.',h:'Wie das Nachfüllprogramm funktioniert',p:'Laut eigenen Markenunterlagen wird die Produktreihe als "4x Award Winning Refillable Korean Skincare" beschrieben, aufgebaut um vier Kernformeln. Der Bubble Tea Steam Cream Nachfüllbeutel (UPC 8809083978402, 50 g) enthält Grape Seed Oil, Beta Glucan, Niacinamide 2% und Adenosine und wird entweder in das ursprüngliche Glas umgefüllt oder unterwegs einzeln verwendet; laut Marke gewann er 2025 den "Best Refillable Skincare"-Award von Prevention Beauty. Die Dewy Glaze Toner Nachfüllung (UPC 8809083978037, 155 g) wird sowohl als Beutel als auch als Reisepackung mit eigenem Verschluss verkauft, und die Marke gibt an, dass sie den Plastikverbrauch im Vergleich zum Kauf einer neuen Flasche jedes Mal um mehr als 90% senkt. Die White Truffle Soufflé Serum Nachfüllung (UPC 8809083977412, 50 ml) und die Be Jelly Overnight Dream Serum Nachfüllung/Reisepackung (UPC 8809083977382, 50 ml) folgen demselben Ansatz und entsprechen jeweils der ursprünglichen Formel; die Marke gibt an, dass die Soufflé Serum Nachfüllung den Plastik- und Glasverbrauch um mehr als 80% senkt. Die Cherry Blossom Sleeping Mask und die Cinnamon Toast Sugar Scrub Foam werden nicht als Nachfüllpackung verkauft.'},
  fr:{title:'Le programme de recharge de Jelly Ko : quatre formules, un système de sachet',excerpt:"Quatre produits Jelly Ko sont vendus avec une recharge en sachet ou un format voyage correspondant ; pour chacun, la marque affirme réduire l'usage de plastique ou de verre de 80 à 90 %.",seoTitle:'Le système de recharge Jelly Ko expliqué · Teranova',seoDesc:"Comment fonctionnent les sachets de recharge Jelly Ko pour le Steam Cream, le Dewy Glaze Toner, le Soufflé Serum et l'Overnight Dream Serum.",h:'Comment fonctionne le programme de recharge',p:'Selon les documents de la marque elle-même, la gamme est présentée comme « 4x Award Winning Refillable Korean Skincare », construite autour de quatre formules principales. La recharge en pochette Bubble Tea Steam Cream (UPC 8809083978402, 50 g) contient Grape Seed Oil, Beta Glucan, Niacinamide 2% et Adenosine ; elle se verse dans le pot d\'origine ou s\'utilise seule en voyage. Selon la marque, elle a remporté le prix "Best Refillable Skincare" de Prevention Beauty en 2025. La recharge Dewy Glaze Toner (UPC 8809083978037, 155 g) est vendue à la fois en pochette et en format voyage avec son propre bouchon, et la marque indique qu\'elle réduit l\'utilisation de plastique de plus de 90% par rapport à l\'achat d\'un nouveau flacon chaque fois. La recharge White Truffle Soufflé Serum (UPC 8809083977412, 50 ml) et la recharge/format voyage Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 ml) suivent la même approche, chacune correspondant à sa formule d\'origine ; la marque indique que la recharge du Soufflé Serum réduit l\'utilisation de plastique et de verre de plus de 80%. Le Cherry Blossom Sleeping Mask et le Cinnamon Toast Sugar Scrub Foam ne sont pas vendus sous forme de recharge.'},
  tr:{title:"Jelly Ko'nun yeniden doldurma programı: dört formül, tek poşet sistemi",excerpt:"Jelly Ko'nun dört ürünü, eşleşen bir yeniden doldurma poşeti veya seyahat paketiyle gönderiliyor; markaya göre her biri plastik veya cam kullanımını %80-90 azaltıyor.",seoTitle:'Jelly Ko yeniden doldurma sistemi açıklandı · Teranova',seoDesc:"Jelly Ko'nun Steam Cream, Dewy Glaze Toner, Soufflé Serum ve Overnight Dream Serum için yeniden doldurma poşetleri nasıl çalışır.",h:'Yeniden doldurma programı nasıl işliyor',p:'Markanın kendi materyallerine göre bu seri, dört ana formül etrafında kurulmuş "4x Award Winning Refillable Korean Skincare" olarak tanımlanıyor. Bubble Tea Steam Cream yedek dolum poşeti (UPC 8809083978402, 50 g) Grape Seed Oil, Beta Glucan, Niacinamide 2% ve Adenosine içerir; orijinal kavanoza boşaltılabilir veya seyahatte tek başına kullanılabilir. Markaya göre bu ürün 2025 yılında Prevention Beauty\'nin "Best Refillable Skincare" ödülünü kazandı. Dewy Glaze Toner yedek dolumu (UPC 8809083978037, 155 g) hem poşet hem de kendi kapağı olan seyahat paketi olarak satılıyor ve marka, her seferinde yeni bir şişe almaya kıyasla plastik kullanımını %90\'ın üzerinde azalttığını belirtiyor. White Truffle Soufflé Serum yedek dolumu (UPC 8809083977412, 50 ml) ve Be Jelly Overnight Dream Serum yedek dolum/seyahat paketi (UPC 8809083977382, 50 ml) aynı yaklaşımı izliyor ve her biri kendi orijinal formülüyle aynı; marka, Soufflé Serum yedek dolumunun plastik ve cam kullanımını %80\'in üzerinde azalttığını belirtiyor. Cherry Blossom Sleeping Mask ve Cinnamon Toast Sugar Scrub Foam yedek dolum olarak satılmıyor.'},
  es:{title:'El programa de recambios de Jelly Ko: cuatro fórmulas, un sistema de bolsa',excerpt:'Cuatro productos de Jelly Ko se venden con una bolsa de recambio o un pack de viaje equivalente, cada uno con la afirmación de la marca de reducir el uso de plástico o vidrio entre un 80 y un 90%.',seoTitle:'El sistema de recambios de Jelly Ko explicado · Teranova',seoDesc:'Cómo funcionan las bolsas de recambio de Jelly Ko para el Steam Cream, el Dewy Glaze Toner, el Soufflé Serum y el Overnight Dream Serum.',h:'Cómo funciona el programa de recambios',p:'Según los materiales propios de la marca, la gama se describe como "4x Award Winning Refillable Korean Skincare", construida alrededor de cuatro fórmulas principales. La bolsa de recarga Bubble Tea Steam Cream (UPC 8809083978402, 50 g) contiene Grape Seed Oil, Beta Glucan, Niacinamide 2% y Adenosine, y se puede verter en el tarro original o usarse sola durante los viajes; según la marca, ganó el premio "Best Refillable Skincare" de Prevention Beauty en 2025. La recarga Dewy Glaze Toner (UPC 8809083978037, 155 g) se vende tanto en bolsa como en formato de viaje con su propio tapón, y la marca declara que reduce el uso de plástico en más de un 90% frente a comprar un frasco nuevo cada vez. La recarga White Truffle Soufflé Serum (UPC 8809083977412, 50 ml) y la recarga/formato de viaje Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 ml) siguen el mismo enfoque, cada una correspondiente a su fórmula original; la marca declara que la recarga del Soufflé Serum reduce el uso de plástico y vidrio en más de un 80%. La Cherry Blossom Sleeping Mask y la Cinnamon Toast Sugar Scrub Foam no se venden como recargas.'},
  pt:{title:'O programa de recargas da Jelly Ko: quatro fórmulas, um sistema de bolsa',excerpt:'Quatro produtos da Jelly Ko são vendidos com uma bolsa de recarga ou pacote de viagem correspondente, cada um com a afirmação da marca de reduzir o uso de plástico ou vidro em 80-90%.',seoTitle:'O sistema de recargas da Jelly Ko explicado · Teranova',seoDesc:'Como funcionam as bolsas de recarga da Jelly Ko para o Steam Cream, o Dewy Glaze Toner, o Soufflé Serum e o Overnight Dream Serum.',h:'Como funciona o programa de recargas',p:'Segundo os próprios materiais da marca, a linha é descrita como "4x Award Winning Refillable Korean Skincare", construída em torno de quatro fórmulas principais. A embalagem de recarga Bubble Tea Steam Cream (UPC 8809083978402, 50 g) contém Grape Seed Oil, Beta Glucan, Niacinamide 2% e Adenosine, podendo ser despejada no pote original ou usada sozinha durante viagens; segundo a marca, ela venceu o prêmio "Best Refillable Skincare" da Prevention Beauty em 2025. A recarga Dewy Glaze Toner (UPC 8809083978037, 155 g) é vendida tanto em formato sachê quanto em embalagem de viagem com tampa própria, e a marca afirma que reduz o uso de plástico em mais de 90% em comparação à compra de um frasco novo todas as vezes. A recarga White Truffle Soufflé Serum (UPC 8809083977412, 50 ml) e a recarga/embalagem de viagem Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 ml) seguem a mesma abordagem, cada uma correspondendo à sua fórmula original; a marca afirma que a recarga do Soufflé Serum reduz o uso de plástico e vidro em mais de 80%. A Cherry Blossom Sleeping Mask e a Cinnamon Toast Sugar Scrub Foam não são vendidas em formato de recarga.'},
  he:{title:'תוכנית המילוי החוזר של Jelly Ko: ארבע פורמולות, מערכת שקית אחת',excerpt:'ארבעה מוצרים של Jelly Ko נמכרים עם שקית מילוי חוזר או אריזת נסיעות מתאימה, וכל אחד מהם, לפי המותג, מפחית שימוש בפלסטיק או בזכוכית ב-80-90%.',seoTitle:'מערכת המילוי החוזר של Jelly Ko מוסברת · Teranova',seoDesc:'כיצד פועלות שקיות המילוי החוזר של Jelly Ko עבור ה-Steam Cream, ה-Dewy Glaze Toner, ה-Soufflé Serum וה-Overnight Dream Serum.',h:'כיצד פועלת תוכנית המילוי החוזר',p:'על פי חומרי המותג עצמו, הקולקציה מוצגת כ-"4x Award Winning Refillable Korean Skincare", הבנויה על בסיס ארבע פורמולות עיקריות. שקית המילוי של Bubble Tea Steam Cream (UPC 8809083978402, 50 גרם) מכילה Grape Seed Oil, Beta Glucan, Niacinamide 2% ו-Adenosine, וניתן למזוג אותה לצנצנת המקורית או להשתמש בה בנפרד בזמן נסיעות; לדברי המותג, המוצר זכה בפרס "Best Refillable Skincare" של Prevention Beauty בשנת 2025. מילוי ה-Dewy Glaze Toner (UPC 8809083978037, 155 גרם) נמכר גם כשקית וגם כאריזת נסיעה עם מכסה נפרד משלה, והמותג מציין כי הוא מפחית את השימוש בפלסטיק בלמעלה מ-90% בהשוואה לרכישת בקבוק חדש בכל פעם. מילוי ה-White Truffle Soufflé Serum (UPC 8809083977412, 50 מ"ל) ומילוי/אריזת הנסיעה של Be Jelly Overnight Dream Serum (UPC 8809083977382, 50 מ"ל) פועלים לפי אותו עקרון, וכל אחד מהם תואם לפורמולה המקורית שלו; המותג מציין כי מילוי ה-Soufflé Serum מפחית את השימוש בפלסטיק ובזכוכית בלמעלה מ-80%. Cherry Blossom Sleeping Mask ו-Cinnamon Toast Sugar Scrub Foam אינם נמכרים כמוצרי מילוי.'},
  hi:{title:'Jelly Ko का रीफिल प्रोग्राम: चार फॉर्मूले, एक पाउच सिस्टम',excerpt:'Jelly Ko के चार उत्पाद एक मिलते-जुलते रीफिल पाउच या ट्रैवल पैक के साथ शिप होते हैं, और ब्रांड के अनुसार हर एक प्लास्टिक या ग्लास के उपयोग को 80-90% तक कम करता है।',seoTitle:'Jelly Ko रीफिल सिस्टम समझाया गया · Teranova',seoDesc:'Steam Cream, Dewy Glaze Toner, Soufflé Serum और Overnight Dream Serum के लिए Jelly Ko के रीफिल पाउच कैसे काम करते हैं।',h:'रीफिल प्रोग्राम कैसे काम करता है',p:'ब्रांड की अपनी सामग्री के अनुसार, इस रेंज को "4x Award Winning Refillable Korean Skincare" के रूप में वर्णित किया गया है, जो चार मुख्य फॉर्मूलों पर आधारित है। Bubble Tea Steam Cream रिफिल पाउच (UPC 8809083978402, 50 g) में Grape Seed Oil, Beta Glucan, Niacinamide 2% और Adenosine शामिल हैं, जिसे मूल जार में डाला जा सकता है या यात्रा के दौरान अलग से इस्तेमाल किया जा सकता है; ब्रांड के अनुसार, इसने 2025 में Prevention Beauty का "Best Refillable Skincare" पुरस्कार जीता। Dewy Glaze Toner रिफिल (UPC 8809083978037, 155 g) पाउच और अपने खुद के कैप वाले ट्रैवल पैक, दोनों रूपों में बिकता है, और ब्रांड का कहना है कि यह हर बार नई बोतल खरीदने की तुलना में प्लास्टिक के उपयोग को 90% से अधिक कम करता है। White Truffle Soufflé Serum रिफिल (UPC 8809083977412, 50 ml) और Be Jelly Overnight Dream Serum रिफिल/ट्रैवल पैक (UPC 8809083977382, 50 ml) भी इसी तरीके का पालन करते हैं, और हर एक अपने मूल फॉर्मूले से मेल खाता है; ब्रांड का कहना है कि Soufflé Serum रिफिल प्लास्टिक और ग्लास के उपयोग को 80% से अधिक कम करता है। Cherry Blossom Sleeping Mask और Cinnamon Toast Sugar Scrub Foam रिफिल के रूप में नहीं बेचे जाते।'},
  ar:{title:'برنامج إعادة التعبئة من Jelly Ko: أربع تركيبات، نظام كيس واحد',excerpt:'تُشحن أربعة منتجات من Jelly Ko مع كيس تعبئة أو عبوة سفر مطابقة، وتذكر العلامة أن كل منها يقلّل استخدام البلاستيك أو الزجاج بنسبة 80-90%.',seoTitle:'نظام إعادة التعبئة من Jelly Ko · Teranova',seoDesc:'كيف تعمل أكياس إعادة التعبئة من Jelly Ko لمنتجات Steam Cream وDewy Glaze Toner وSoufflé Serum وOvernight Dream Serum.',h:'كيف يعمل برنامج إعادة التعبئة',p:'تصف مواد العلامة الخاصة هذه التشكيلة بأنها "4x Award Winning Refillable Korean Skincare" (عناية كورية قابلة لإعادة التعبئة حائزة على 4 جوائز)، وتتمحور حول أربع تركيبات أساسية. يحتوي كيس تعبئة Bubble Tea Steam Cream (رمز UPC 8809083978402، 50 غ) على Grape Seed Oil وBeta Glucan وNiacinamide بنسبة 2% وAdenosine، ويُسكب في العبوة الأصلية أو يُستخدم بمفرده أثناء السفر؛ وبحسب العلامة، فاز بجائزة "Best Refillable Skincare" من Prevention Beauty في عام 2025. تُباع إعادة تعبئة Dewy Glaze Toner (رمز UPC 8809083978037، 155 غ) على شكل كيس وعبوة سفر بغطائها الخاص، وتذكر العلامة أنها تقلّل استخدام البلاستيك بأكثر من 90% مقارنة بشراء زجاجة جديدة كل مرة. تتبع إعادة تعبئة White Truffle Soufflé Serum (رمز UPC 8809083977412، 50 مل) وإعادة تعبئة/عبوة سفر Be Jelly Overnight Dream Serum (رمز UPC 8809083977382، 50 مل) نفس النهج، وتطابق كل منهما التركيبة الأصلية؛ وتذكر العلامة أن إعادة تعبئة Soufflé Serum تقلّل استخدام البلاستيك والزجاج بأكثر من 80%. لا يُباع Cherry Blossom Sleeping Mask وCinnamon Toast Sugar Scrub Foam كإعادة تعبئة.'},
});

const awardsMarkets = make({
  ru:{title:'Jelly Ko: награды, 1% for the Planet и рынки продаж',excerpt:'Награды Jelly Ko от Prevention Beauty, участие в 1% for the Planet и рынки, где бренд заявляет о продажах.',seoTitle:'Награды и рынки Jelly Ko · Teranova',seoDesc:'Награды Jelly Ko от Prevention Beauty, участие в 1% for the Planet, продажи в Австралии, США и по всему миру через YesStyle.',h:'Награды, участие в программах и рынки продаж',p:'По собственным материалам бренда, Jelly Ko получил несколько наград Prevention Beauty: рефилл Bubble Tea Steam Cream — «Best Refillable Skincare» (2025), Cherry Blossom Sleeping Mask — «Best Sleep Mask» (2023), Gelato Glaze Lip Mask — «Lip Glaze» в рамках Best of Beauty Awards 2024 года, и Jelly Shield Pimple Patches — «Best Pimple Patches» (2025); маска для губ поставляется в коробке из переработанной бумаги с соевыми чернилами и цинковой ложечкой-скупом, выполняющей также роль мини-гуаши. Бренд указывает себя участником программы 1% for the Planet и заявляет, что с 2023 года направляет не менее 1% годовой выручки экологическим некоммерческим организациям. По собственным материалам, Jelly Ko продаётся по всему миру через YesStyle, в Австралии — через аптеки, Woolworths и Amazon, в США — через C.O. Bigelow и ecosmetics.com; свою аудиторию бренд описывает как «женщины 25–55+». На упаковке каждого проверенного для этого каталога SKU стоит маркировка «Made in Korea».'},
  en:{title:"Jelly Ko: awards, 1% for the Planet and where it sells",excerpt:"Jelly Ko's Prevention Beauty awards, its 1% for the Planet membership, and the markets where the brand says it is sold.",seoTitle:'Jelly Ko awards and markets · Teranova',seoDesc:"Jelly Ko's Prevention Beauty awards, 1% for the Planet membership and distribution in Australia, the US and globally via YesStyle.",h:'Awards, membership and where it sells',p:'Per its own brand materials, Jelly Ko has won several Prevention Beauty awards: the Bubble Tea Steam Cream Refill for "Best Refillable Skincare" (2025), the Cherry Blossom Sleeping Mask for "Best Sleep Mask" (2023), the Gelato Glaze Lip Mask for "Lip Glaze" in its 2024 Best of Beauty Awards, and the Jelly Shield Pimple Patches for "Best Pimple Patches" (2025); the Lip Mask ships in a recycled-paper box with soy ink and a zinc scoop that doubles as a mini gua sha tool. The brand lists itself as a member of 1% for the Planet and states it has donated at least 1% of annual revenue to environmental nonprofits every year since 2023. Per its own materials, Jelly Ko sells globally through YesStyle, in Australia through pharmacies, Woolworths and Amazon, and in the United States through C.O. Bigelow and ecosmetics.com; the brand describes its audience as "women 25-55+." Every SKU reviewed for this catalog carries a "Made in Korea" mark on its packaging.'},
  ko:{title:'젤리코: 수상 내역, 1% for the Planet, 그리고 판매 지역',excerpt:'젤리코의 Prevention Beauty 수상 내역, 1% for the Planet 멤버십, 그리고 브랜드가 밝힌 판매 지역.',seoTitle:'젤리코 수상 내역과 판매 지역 · Teranova',seoDesc:'젤리코의 Prevention Beauty 수상 내역, 1% for the Planet 멤버십, 그리고 호주·미국 및 YesStyle을 통한 글로벌 유통.',h:'수상 내역, 멤버십, 판매 지역',p:'브랜드 자체 자료에 따르면 Jelly Ko는 Prevention Beauty에서 여러 상을 수상했다: Bubble Tea Steam Cream Refill은 "Best Refillable Skincare"(2025), Cherry Blossom Sleeping Mask는 "Best Sleep Mask"(2023), Gelato Glaze Lip Mask는 2024년 Best of Beauty Awards에서 "Lip Glaze", Jelly Shield Pimple Patches는 "Best Pimple Patches"(2025)를 수상했다. 이 Lip Mask는 재생 용지 박스에 콩기름 잉크로 인쇄되어 있으며, 미니 괄사(gua sha) 도구로도 사용할 수 있는 아연 스쿱이 함께 제공된다. 브랜드는 자사가 1% for the Planet의 회원이라고 소개하며, 2023년 이후 매년 연간 매출의 1% 이상을 환경 비영리단체에 기부했다고 밝힌다. 브랜드 자체 자료에 따르면 Jelly Ko는 전 세계적으로 YesStyle을 통해, 호주에서는 약국, Woolworths, Amazon을 통해, 미국에서는 C.O. Bigelow와 ecosmetics.com을 통해 판매된다. 브랜드는 자사의 타깃 고객을 "women 25-55+"로 설명한다. 이 카탈로그를 위해 검토된 모든 SKU의 포장에는 "Made in Korea" 표시가 있다.'},
  zh:{title:'Jelly Ko:获奖记录、1% for the Planet与销售渠道',excerpt:'Jelly Ko的Prevention Beauty获奖记录、1% for the Planet会员资格,以及品牌所说的销售市场。',seoTitle:'Jelly Ko的获奖记录与销售市场 · Teranova',seoDesc:'Jelly Ko的Prevention Beauty获奖记录、1% for the Planet会员资格,以及通过YesStyle在澳大利亚、美国及全球的分销情况。',h:'获奖记录、会员资格与销售渠道',p:'据品牌自身资料介绍,Jelly Ko曾多次获得Prevention Beauty奖项:Bubble Tea Steam Cream Refill获得"Best Refillable Skincare"(2025年),Cherry Blossom Sleeping Mask获得"Best Sleep Mask"(2023年),Gelato Glaze Lip Mask在2024年Best of Beauty Awards中获得"Lip Glaze"奖项,Jelly Shield Pimple Patches获得"Best Pimple Patches"(2025年);该Lip Mask采用再生纸包装盒,使用豆油墨印刷,并配有可兼作迷你刮痧工具的锌质刮勺。品牌表示自身是1% for the Planet的成员,并称自2023年以来每年将至少1%的年营收捐赠给环保非营利组织。据品牌自身资料介绍,Jelly Ko通过YesStyle在全球销售,在澳大利亚通过药房、Woolworths和Amazon销售,在美国通过C.O. Bigelow和ecosmetics.com销售;品牌将其受众描述为"women 25-55+"。本目录所评估的每款SKU包装上均标有"Made in Korea"标识。'},
  ja:{title:'Jelly Ko:受賞歴、1% for the Planet、販売地域',excerpt:'Jelly KoのPrevention Beauty受賞歴、1% for the Planetへの参加、そしてブランドが述べる販売市場について。',seoTitle:'Jelly Koの受賞歴と販売市場 · Teranova',seoDesc:'Jelly KoのPrevention Beauty受賞歴、1% for the Planetへの参加、そしてYesStyleを通じたオーストラリア・米国・グローバルでの販売。',h:'受賞歴、参加プログラム、販売地域',p:'ブランド自身の資料によると、Jelly KoはPrevention Beautyの複数の賞を受賞している:Bubble Tea Steam Cream Refillが「Best Refillable Skincare」(2025年)、Cherry Blossom Sleeping Maskが「Best Sleep Mask」(2023年)、Gelato Glaze Lip Maskが2024年のBest of Beauty Awardsで「Lip Glaze」、Jelly Shield Pimple Patchesが「Best Pimple Patches」(2025年)を受賞した。このLip Maskは再生紙のボックスに大豆インクで印刷され、ミニグアシャツールとしても使える亜鉛製のスクープが付属する。ブランドは自社が1% for the Planetの会員であるとし、2023年以降毎年、年間収益の1%以上を環境関連の非営利団体に寄付していると述べている。ブランド自身の資料によると、Jelly Koは世界的にはYesStyleを通じて、オーストラリアでは薬局、Woolworths、Amazonを通じて、米国ではC.O. Bigelowとecosmetics.comを通じて販売されている。ブランドは自社のターゲット層を「women 25-55+」と説明している。本カタログで確認された全SKUのパッケージには「Made in Korea」の表示がある。'},
  it:{title:'Jelly Ko: premi, 1% for the Planet e dove viene venduto',excerpt:"I premi Prevention Beauty di Jelly Ko, la sua adesione a 1% for the Planet e i mercati in cui il marchio dichiara di essere venduto.",seoTitle:'Premi e mercati di Jelly Ko · Teranova',seoDesc:"I premi Prevention Beauty di Jelly Ko, l'adesione a 1% for the Planet e la distribuzione in Australia, negli Stati Uniti e a livello globale tramite YesStyle.",h:'Premi, adesione e dove viene venduto',p:'Secondo i materiali del marchio stesso, Jelly Ko ha vinto diversi premi Prevention Beauty: il Bubble Tea Steam Cream Refill per "Best Refillable Skincare" (2025), il Cherry Blossom Sleeping Mask per "Best Sleep Mask" (2023), il Gelato Glaze Lip Mask per "Lip Glaze" nei Best of Beauty Awards 2024, e le Jelly Shield Pimple Patches per "Best Pimple Patches" (2025); la Lip Mask viene spedita in una scatola di carta riciclata con inchiostro di soia e una paletta di zinco che funge anche da mini strumento per il gua sha. Il marchio si presenta come membro di 1% for the Planet e dichiara di aver donato almeno l\'1% dei ricavi annuali a organizzazioni non profit ambientali ogni anno dal 2023. Secondo i propri materiali, Jelly Ko vende a livello globale tramite YesStyle, in Australia tramite farmacie, Woolworths e Amazon, e negli Stati Uniti tramite C.O. Bigelow ed ecosmetics.com; il marchio descrive il proprio pubblico come "women 25-55+". Ogni SKU esaminato per questo catalogo presenta sulla confezione il marchio "Made in Korea".'},
  de:{title:'Jelly Ko: Auszeichnungen, 1% for the Planet und Vertriebsmärkte',excerpt:'Die Prevention-Beauty-Auszeichnungen von Jelly Ko, die Mitgliedschaft bei 1% for the Planet und die Märkte, in denen die Marke nach eigenen Angaben verkauft wird.',seoTitle:'Jelly Ko: Auszeichnungen und Märkte · Teranova',seoDesc:'Die Prevention-Beauty-Awards von Jelly Ko, die Mitgliedschaft bei 1% for the Planet und der Vertrieb in Australien, den USA und weltweit über YesStyle.',h:'Auszeichnungen, Mitgliedschaft und Vertriebsmärkte',p:'Laut eigenen Markenunterlagen hat Jelly Ko mehrere Prevention-Beauty-Awards gewonnen: das Bubble Tea Steam Cream Refill für "Best Refillable Skincare" (2025), die Cherry Blossom Sleeping Mask für "Best Sleep Mask" (2023), die Gelato Glaze Lip Mask für "Lip Glaze" bei den Best of Beauty Awards 2024 und die Jelly Shield Pimple Patches für "Best Pimple Patches" (2025); die Lip Mask wird in einer Box aus recyceltem Papier mit Sojatinte verschickt, zusammen mit einem Zink-Löffel, der auch als Mini-Gua-Sha-Werkzeug dient. Die Marke bezeichnet sich selbst als Mitglied von 1% for the Planet und gibt an, seit 2023 jedes Jahr mindestens 1% des Jahresumsatzes an gemeinnützige Umweltorganisationen gespendet zu haben. Laut eigenen Unterlagen verkauft Jelly Ko weltweit über YesStyle, in Australien über Apotheken, Woolworths und Amazon sowie in den USA über C.O. Bigelow und ecosmetics.com; die Marke beschreibt ihre Zielgruppe als "women 25-55+". Jedes für diesen Katalog geprüfte SKU trägt auf der Verpackung die Kennzeichnung "Made in Korea".'},
  fr:{title:'Jelly Ko : récompenses, 1% for the Planet et points de vente',excerpt:"Les prix Prevention Beauty de Jelly Ko, son adhésion à 1% for the Planet, et les marchés où la marque indique être vendue.",seoTitle:'Récompenses et marchés de Jelly Ko · Teranova',seoDesc:"Les prix Prevention Beauty de Jelly Ko, son adhésion à 1% for the Planet et sa distribution en Australie, aux États-Unis et dans le monde via YesStyle.",h:'Récompenses, adhésion et points de vente',p:'Selon les documents de la marque elle-même, Jelly Ko a remporté plusieurs prix Prevention Beauty : le Bubble Tea Steam Cream Refill pour "Best Refillable Skincare" (2025), le Cherry Blossom Sleeping Mask pour "Best Sleep Mask" (2023), le Gelato Glaze Lip Mask pour "Lip Glaze" lors des Best of Beauty Awards 2024, et les Jelly Shield Pimple Patches pour "Best Pimple Patches" (2025) ; le Lip Mask est expédié dans une boîte en papier recyclé imprimée à l\'encre de soja, avec une cuillère en zinc qui fait aussi office de mini-outil de gua sha. La marque se présente comme membre de 1% for the Planet et déclare avoir reversé au moins 1% de son chiffre d\'affaires annuel à des organisations environnementales à but non lucratif chaque année depuis 2023. Selon ses propres documents, Jelly Ko est vendue dans le monde via YesStyle, en Australie en pharmacie, chez Woolworths et sur Amazon, et aux États-Unis via C.O. Bigelow et ecosmetics.com ; la marque décrit son public comme "women 25-55+". Chaque référence examinée pour ce catalogue porte la mention "Made in Korea" sur son emballage.'},
  tr:{title:'Jelly Ko: ödüller, 1% for the Planet ve satış yapılan pazarlar',excerpt:'Jelly Ko\'nun Prevention Beauty ödülleri, 1% for the Planet üyeliği ve markanın satıldığını belirttiği pazarlar.',seoTitle:'Jelly Ko ödülleri ve pazarları · Teranova',seoDesc:'Jelly Ko\'nun Prevention Beauty ödülleri, 1% for the Planet üyeliği ve Avustralya, ABD ve YesStyle üzerinden küresel dağıtımı.',h:'Ödüller, üyelik ve satış yapılan pazarlar',p:'Markanın kendi materyallerine göre Jelly Ko, Prevention Beauty\'den birkaç ödül kazandı: Bubble Tea Steam Cream Refill "Best Refillable Skincare" (2025), Cherry Blossom Sleeping Mask "Best Sleep Mask" (2023), Gelato Glaze Lip Mask 2024 Best of Beauty Awards\'ta "Lip Glaze", ve Jelly Shield Pimple Patches "Best Pimple Patches" (2025) ödülünü aldı; Lip Mask, soya mürekkebiyle basılmış geri dönüştürülmüş kağıt kutuda gönderiliyor ve mini gua sha aracı olarak da kullanılabilen çinko bir kaşıkla birlikte geliyor. Marka kendisini 1% for the Planet üyesi olarak tanıtıyor ve 2023\'ten bu yana her yıl yıllık gelirinin en az %1\'ini çevre amaçlı kâr amacı gütmeyen kuruluşlara bağışladığını belirtiyor. Kendi materyallerine göre Jelly Ko, dünya çapında YesStyle üzerinden, Avustralya\'da eczaneler, Woolworths ve Amazon üzerinden, Amerika Birleşik Devletleri\'nde ise C.O. Bigelow ve ecosmetics.com üzerinden satılıyor; marka hedef kitlesini "women 25-55+" olarak tanımlıyor. Bu katalog için incelenen her SKU\'nun ambalajında "Made in Korea" işareti bulunuyor.'},
  es:{title:'Jelly Ko: premios, 1% for the Planet y dónde se vende',excerpt:'Los premios Prevention Beauty que ha ganado Jelly Ko, su membresía en 1% for the Planet y los mercados donde la marca afirma que se vende.',seoTitle:'Premios y mercados de Jelly Ko · Teranova',seoDesc:'Los premios Prevention Beauty de Jelly Ko, su membresía en 1% for the Planet y su distribución en Australia, Estados Unidos y a nivel global a través de YesStyle.',h:'Premios, membresía y dónde se vende',p:'Según los materiales propios de la marca, Jelly Ko ha ganado varios premios Prevention Beauty: el Bubble Tea Steam Cream Refill por "Best Refillable Skincare" (2025), la Cherry Blossom Sleeping Mask por "Best Sleep Mask" (2023), la Gelato Glaze Lip Mask por "Lip Glaze" en los Best of Beauty Awards de 2024, y las Jelly Shield Pimple Patches por "Best Pimple Patches" (2025); la Lip Mask se envía en una caja de papel reciclado con tinta de soja y una cuchara de zinc que también funciona como mini herramienta de gua sha. La marca se presenta como miembro de 1% for the Planet y declara haber donado al menos el 1% de sus ingresos anuales a organizaciones ambientales sin fines de lucro cada año desde 2023. Según sus propios materiales, Jelly Ko se vende globalmente a través de YesStyle, en Australia a través de farmacias, Woolworths y Amazon, y en Estados Unidos a través de C.O. Bigelow y ecosmetics.com; la marca describe a su público como "women 25-55+". Cada SKU revisado para este catálogo lleva la marca "Made in Korea" en su empaque.'},
  pt:{title:'Jelly Ko: premiações, 1% for the Planet e onde é vendida',excerpt:'Os prêmios Prevention Beauty conquistados pela Jelly Ko, sua participação no 1% for the Planet e os mercados em que a marca afirma estar presente.',seoTitle:'Premiações e mercados da Jelly Ko · Teranova',seoDesc:'Os prêmios Prevention Beauty da Jelly Ko, sua participação no 1% for the Planet e a distribuição na Austrália, nos Estados Unidos e globalmente via YesStyle.',h:'Premiações, participação e onde é vendida',p:'Segundo os próprios materiais da marca, a Jelly Ko já venceu vários prêmios da Prevention Beauty: o Bubble Tea Steam Cream Refill por "Best Refillable Skincare" (2025), a Cherry Blossom Sleeping Mask por "Best Sleep Mask" (2023), a Gelato Glaze Lip Mask por "Lip Glaze" nos Best of Beauty Awards de 2024, e os Jelly Shield Pimple Patches por "Best Pimple Patches" (2025); a Lip Mask é enviada em uma caixa de papel reciclado com tinta de soja e uma colher de zinco que também funciona como mini ferramenta de gua sha. A marca se apresenta como membro da 1% for the Planet e afirma ter doado pelo menos 1% da receita anual a organizações ambientais sem fins lucrativos todos os anos desde 2023. Segundo seus próprios materiais, a Jelly Ko vende globalmente pela YesStyle, na Austrália por farmácias, Woolworths e Amazon, e nos Estados Unidos pela C.O. Bigelow e ecosmetics.com; a marca descreve seu público como "women 25-55+". Todo SKU analisado para este catálogo traz a marcação "Made in Korea" na embalagem.'},
  he:{title:'Jelly Ko: פרסים, 1% for the Planet והיכן הוא נמכר',excerpt:'זכיות Jelly Ko בפרסי Prevention Beauty, חברותו ב-1% for the Planet, והשווקים שבהם המותג מצהיר שהוא נמכר.',seoTitle:'פרסים ושווקים של Jelly Ko · Teranova',seoDesc:'פרסי Prevention Beauty של Jelly Ko, חברותו ב-1% for the Planet וההפצה שלו באוסטרליה, בארצות הברית ובעולם באמצעות YesStyle.',h:'פרסים, חברות והיכן הוא נמכר',p:'על פי חומרי המותג עצמו, Jelly Ko זכתה בכמה פרסים של Prevention Beauty: Bubble Tea Steam Cream Refill בפרס "Best Refillable Skincare" (2025), Cherry Blossom Sleeping Mask בפרס "Best Sleep Mask" (2023), Gelato Glaze Lip Mask בפרס "Lip Glaze" במסגרת Best of Beauty Awards לשנת 2024, ו-Jelly Shield Pimple Patches בפרס "Best Pimple Patches" (2025); ה-Lip Mask מגיע באריזת קרטון ממוחזר המודפסת בדיו סויה, עם כפית אבץ שמשמשת גם כמכשיר גואה שה מיני. המותג מציג את עצמו כחבר ב-1% for the Planet ומציין כי מאז 2023 הוא תורם בכל שנה לפחות 1% מההכנסה השנתית שלו לעמותות סביבתיות. על פי חומריו שלו, Jelly Ko נמכר באופן גלובלי באמצעות YesStyle, באוסטרליה באמצעות בתי מרקחת, Woolworths ו-Amazon, ובארצות הברית באמצעות C.O. Bigelow ו-ecosmetics.com; המותג מתאר את קהל היעד שלו כ-"women 25-55+". כל מק"ט שנבדק לצורך הקטלוג הזה נושא על האריזה שלו את הסימון "Made in Korea".'},
  hi:{title:'Jelly Ko: पुरस्कार, 1% for the Planet और यह कहाँ बिकता है',excerpt:'Jelly Ko की Prevention Beauty जीतें, इसकी 1% for the Planet सदस्यता, और वे बाज़ार जहाँ ब्रांड का कहना है कि वह बिकता है।',seoTitle:'Jelly Ko के पुरस्कार और बाज़ार · Teranova',seoDesc:'Jelly Ko के Prevention Beauty पुरस्कार, 1% for the Planet सदस्यता, और ऑस्ट्रेलिया, अमेरिका और YesStyle के ज़रिए दुनिया भर में इसका वितरण।',h:'पुरस्कार, सदस्यता और यह कहाँ बिकता है',p:'ब्रांड की अपनी सामग्री के अनुसार, Jelly Ko ने Prevention Beauty के कई पुरस्कार जीते हैं: Bubble Tea Steam Cream Refill ने "Best Refillable Skincare" (2025), Cherry Blossom Sleeping Mask ने "Best Sleep Mask" (2023), Gelato Glaze Lip Mask ने अपने 2024 Best of Beauty Awards में "Lip Glaze", और Jelly Shield Pimple Patches ने "Best Pimple Patches" (2025) जीता; यह Lip Mask रीसाइकल्ड पेपर बॉक्स में सोया इंक के साथ भेजा जाता है, और इसके साथ एक जिंक स्कूप आता है जो मिनी गुआ शा टूल के रूप में भी काम करता है। ब्रांड खुद को 1% for the Planet का सदस्य बताता है और कहता है कि उसने 2023 से हर साल अपनी वार्षिक आय का कम से कम 1% पर्यावरण संबंधी गैर-लाभकारी संगठनों को दान किया है। ब्रांड की अपनी सामग्री के अनुसार, Jelly Ko दुनिया भर में YesStyle के माध्यम से, ऑस्ट्रेलिया में फार्मेसियों, Woolworths और Amazon के माध्यम से, और संयुक्त राज्य अमेरिका में C.O. Bigelow और ecosmetics.com के माध्यम से बिकता है; ब्रांड अपने दर्शकों को "women 25-55+" के रूप में वर्णित करता है। इस कैटलॉग के लिए जांचे गए हर SKU की पैकेजिंग पर "Made in Korea" का निशान है।'},
  ar:{title:'Jelly Ko: الجوائز وعضوية 1% for the Planet وأسواق البيع',excerpt:'جوائز Jelly Ko من Prevention Beauty، وعضويتها في 1% for the Planet، والأسواق التي تذكر العلامة أنها تُباع فيها.',seoTitle:'جوائز Jelly Ko وأسواقها · Teranova',seoDesc:'جوائز Jelly Ko من Prevention Beauty، وعضوية 1% for the Planet، والتوزيع في أستراليا والولايات المتحدة وعالميًا عبر YesStyle.',h:'الجوائز والعضوية وأسواق البيع',p:'بحسب مواد العلامة الخاصة، فازت Jelly Ko بعدة جوائز من Prevention Beauty: حصلت Bubble Tea Steam Cream Refill على جائزة "Best Refillable Skincare" (2025)، وحصل Cherry Blossom Sleeping Mask على جائزة "Best Sleep Mask" (2023)، وحصل Gelato Glaze Lip Mask على جائزة "Lip Glaze" في إطار Best of Beauty Awards لعام 2024، وحصلت Jelly Shield Pimple Patches على جائزة "Best Pimple Patches" (2025)؛ ويُشحن Lip Mask في صندوق من ورق معاد تدويره مطبوع بحبر الصويا، مع ملعقة من الزنك تُستخدم أيضًا كأداة غوا شا صغيرة. تُعرّف العلامة نفسها كعضو في 1% for the Planet وتذكر أنها تبرعت كل عام منذ 2023 بما لا يقل عن 1% من إيراداتها السنوية لمنظمات بيئية غير ربحية. وبحسب موادها الخاصة، تُباع Jelly Ko عالميًا عبر YesStyle، وفي أستراليا عبر الصيدليات وWoolworths وAmazon، وفي الولايات المتحدة عبر C.O. Bigelow وecosmetics.com؛ وتصف العلامة جمهورها بأنه "women 25-55+" (النساء من عمر 25 إلى 55 عامًا فما فوق). تحمل كل وحدة SKU تمت مراجعتها لهذا الكتالوج علامة "Made in Korea" على عبوتها.'},
});

